import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
const [nextNm, astroNm, article] = process.argv.slice(2);
const reqN = createRequire(nextNm + "/");
const jsyaml = reqN("js-yaml"); const gm = reqN("gray-matter");
const { parse: yamlParse } = await import(astroNm + "/yaml/dist/index.js");
const { parseFrontmatter } = await import(astroNm + "/@astrojs/internal-helpers/dist/frontmatter.js");
const text = readFileSync(article, "utf8");
const fieldRe = (k) => new RegExp(`^${k}: .*$`, "m");
const oldBreak = (t) => t.replace(fieldRe("title"), (line) => line.replace(/"$/, "") + "\n  : [unbalanced");
const newBreak = (t) => t.replace(fieldRe("title"), "title: [unbalanced");
const fm = (t) => t.split("\n---\n")[0].replace(/^---\n/, "");
for (const [name, f] of [["title-unbalanced-quote-v1 (old)", oldBreak], ["unclosed-flow-sequence-v1 (new)", newBreak]]) {
  const t = f(text);
  const y = fm(t);
  const r = {};
  try { const v = jsyaml.safeLoad(y); r.jsyaml = "parsed: title=" + JSON.stringify(v.title); } catch (e) { r.jsyaml = "ERROR " + e.name + ": " + e.message.split("\n")[0]; }
  try { const v = gm(t); r.grayMatter = "parsed: title=" + JSON.stringify(v.data.title); } catch (e) { r.grayMatter = "ERROR " + e.name + ": " + e.message.split("\n")[0]; }
  try { const v = yamlParse(y); r.yaml = "parsed: title=" + JSON.stringify(v.title); } catch (e) { r.yaml = "ERROR " + e.name + ": " + e.message.split("\n")[0]; }
  try { const v = parseFrontmatter(t, { frontmatter: "empty-with-spaces" }); r.astroParseFrontmatter = "parsed: title=" + JSON.stringify(v.frontmatter.title); } catch (e) { r.astroParseFrontmatter = "ERROR " + e.name + ": " + e.message.split("\n")[0]; }
  console.log(JSON.stringify({ variant: name, ...r }, null, 1));
}
console.log("versions", reqN("js-yaml/package.json").version, reqN("gray-matter/package.json").version, JSON.parse(readFileSync(astroNm + "/yaml/package.json")).version, JSON.parse(readFileSync(astroNm + "/@astrojs/internal-helpers/package.json")).version);
